1780126405381.css:
.card {
  font-family: Arial, sans-serif;
  font-size: 22px;
  text-align: center;
  color: #ffffff;
  background-color: #1e1e1e;
}

.english {
  font-size: 24px;
  line-height: 1.45;
  margin: 12px 0 22px 0;
}

.sectionlabel {
  font-size: 13px;
  letter-spacing: 0.12em;
  text-transform: uppercase;
  opacity: 0.65;
  margin: 18px 0 6px 0;
}

.sentence-hanzi-rendered {
  font-size: 40px;
  line-height: 1.8;
  margin: 4px 0 12px 0;
}

.inline-hanzi-char {
  display: inline-block;
  width: 1.18em;
  height: 1.18em;
  vertical-align: -0.22em;
}

.static-char {
  background: transparent;
  margin: 0;
}

.focus-char {
  background: transparent;
  border: 1px solid rgba(255,255,255,0.28);
  border-radius: 0.22em;
  margin: 0 0.04em;
  box-shadow: none;
}

.sentence-text {
  display: inline;
  white-space: pre-wrap;
}

.pinyin {
  font-size: 24px;
  line-height: 1.45;
  margin-top: 4px;
}

.nodiacritic-wrapper {
  margin: 14px 0 0 0;
  text-align: center;
}

.nodiacritic-button {
  display: inline-block;
  cursor: pointer;
  font-size: 18px;
  line-height: 1.35;
  padding: 5px 12px;
  border: 1px solid rgba(255,255,255,0.28);
  border-radius: 0.35em;
  background: transparent;
  color: #ffffff;
  font-family: Arial, sans-serif;
  user-select: none;
}

.nodiacritic-button:hover {
  background: rgba(255,255,255,0.08);
}

.nodiacritic-button:active {
  background: rgba(255,255,255,0.12);
}

