1780202277551.css:
@font-face {
  font-family: "LXGWSC";
  src: url("_LXGWSC.ttf");
}

@font-face {
  font-family: "LXGWTC";
  src: url("_LXGWTC.ttf");
}

.card {
  background-color: #2b2b2b;
  color: white;
  text-align: center;
  padding: 28px;
}

.audiofront {
  margin-top: 80px;
  margin-bottom: 28px;
  text-align: center;
}

.audioreplay {
  margin-top: 30px;
  text-align: center;
}

.frontnote {
  font-family: Arial, sans-serif;
  font-size: 14px;
  color: #888888;
  margin-top: 18px;
  letter-spacing: 0.5px;
}

.english {
  font-family: Arial, sans-serif;
  font-size: 22px;
  margin-bottom: 28px;
  line-height: 1.4;
}

.sectionlabel {
  font-family: Arial, sans-serif;
  font-size: 11px;
  color: #777777;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 10px;
  margin-top: 10px;
}

.simp {
  font-family: "LXGWSC", "KaiTi", serif;
  font-size: 32px;
  line-height: 1.5;
  letter-spacing: 1px;
  margin-bottom: 28px;
  background-color: rgba(255,255,255,0.03);
  border-radius: 12px;
  padding: 18px;
}

.trad {
  font-family: "LXGWTC", "BiauKai", "DFKai-SB", serif;
  font-size: 33px;
  line-height: 1.5;
  letter-spacing: 1px;
  margin-bottom: 28px;
  background-color: rgba(255,255,255,0.03);
  border-radius: 12px;
  padding: 18px;
}

.pinyin {
  font-family: Arial, sans-serif;
  font-size: 20px;
  color: #BBBBBB;
  margin-top: 6px;
}

