  font-family: "NotoSC";
  src: url("_NotoSC.ttf");
}

@font-face {
  font-family: "NotoTC";
  src: url("_NotoTC.ttf");
}

.card {
  background-color: #2b2b2b;
  color: white;
  text-align: center;
  padding: 28px;
}

.english {
  font-family: Arial, sans-serif;
  font-size: 22px;
  margin-bottom: 28px;
  line-height: 1.4;
}

.sectionlabel {
  font-family: Arial, sans-serif;
  font-size: 11px;
  color: #777777;
  text-transform: uppercase;
  letter-spacing: 2px;
  margin-bottom: 10px;
  margin-top: 10px;
}

.simp {
  font-family: "NotoSC";
  font-size: 30px;
  line-height: 1.5;
  letter-spacing: 1px;
  margin-bottom: 28px;
  background-color: rgba(255,255,255,0.03);
  border-radius: 12px;
  padding: 18px;
}

.trad {
  font-family: "NotoTC";
  font-size: 31px;
  line-height: 1.5;
  letter-spacing: 1px;
  margin-bottom: 28px;
  background-color: rgba(255,255,255,0.03);
  border-radius: 12px;
  padding: 18px;
}

.pinyin {
  font-family: Arial, sans-serif;
  font-size: 20px;
  color: #BBBBBB;
  margin-top: 6px;
}

/*
Adds invisible space beneath the front of the card on phones.
This allows the final lines to be scrolled fully above the keyboard.
*/
.keyboard-scroll-space {
  display: none;
}

@media (max-width: 600px) {
  .keyboard-scroll-space {
    display: block;
    height: 55vh;
    min-height: 360px;
    pointer-events: none;
  }
}

.type-answer-result {
  margin-top: 28px;
}

